document.addEventListener("DOMContentLoaded",()=>{document.getElementById("authentication").addEventListener("submit",function(e){e.preventDefault();const t=new URLSearchParams(new FormData(this));fetch(this.action,{method:"POST",body:t}).then(async e=>{if(e.ok)location.assign(e.headers.get("goto"));else{switch(e.status){case 423:createPopup("Your account has been locked",1e4);break;case 409:createPopup(`An account with the username '${this.username.value}' already exists`,5e3);break;default:createPopup(errorStatus(e.status.toString()),3500)}document.querySelectorAll("#captcha").forEach(e=>e.remove()),appendWidget()}})})});